from produire import produire
from format_lecon import paras,table,steps

p=[
('L’{abcès périamygdalien} est une collection purulente autour d’une amygdale palatine. Il se distingue d’une amygdalite simple et d’une inflammation sans collection. La priorité est d’évaluer la voie aérienne et l’extension.',paras('Les termes abcès péritonsillaire et abcès périamygdalien désignent la même localisation. Le diagnostic ne repose pas sur la seule présence d’exsudat sur une amygdale.', 'Une infection rétropharyngée ou parapharyngée siège dans un autre espace cervical et peut nécessiter un bilan plus large.')),
('Le {contexte est souvent une infection amygdalienne}. Il s’agit d’une complication suppurative reconnue. Son rang quantitatif parmi tous les maux de gorge n’est pas établi ici.',paras('La revue suisse 2015 décrit l’abcès péritonsillaire comme l’une des infections profondes des tissus mous du cou les plus fréquentes. Cette appréciation ne permet pas d’en déduire une incidence suisse actuelle.', 'Une infection EBV peut aussi être associée. Le caractère viral d’une angine initiale n’élimine donc pas la recherche d’une suppuration secondaire devant une évolution focale.')),
('La {collection déforme les tissus voisins}. Le bombement du voile et la douleur à l’ouverture buccale s’expliquent par cette extension. L’antibiotique seul ne remplace pas toujours le contrôle du foyer.',table(['Lésion','Exploration','Traitement lié au mécanisme'],[['Collection autour de l’amygdale.','Asymétrie du voile ; évaluation ORL et ponction selon indication.','Évacuation du pus lorsque nécessaire.'],['Inflammation des tissus voisins.','Trismus et douleur ; recherche d’une extension.','Antibiothérapie et traitement antalgique adaptés.'],['Retentissement sur déglutition ou respiration.','Capacité à boire, salive, voix et effort respiratoire.','Hydratation assistée ou sécurisation de la voie aérienne selon gravité.']])+paras('La flore peut être mixte, avec streptocoques et anaérobies selon la revue suisse. Le choix antibiotique dépend du foyer, des allergies, des prélèvements et du protocole hospitalier.')),
('Le {tri recherche obstruction et extension profonde}. Une présentation unilatérale douloureuse nécessite un avis urgent. Un sepsis change immédiatement la priorité.',table(['Diagnostic à distinguer','Indice','Action'],[['🚩 Épiglottite.','Stridor ou salivation avec douleur peu expliquée par la bouche.','Prise en charge respiratoire spécialisée.'],['🚩 Abcès rétropharyngé.','Torticolis, tuméfaction cervicale ou pharyngée postérieure.','Imagerie si stabilité et avis urgent.'],['🚩 Lemierre.','Reprise fébrile, douleur jugulaire et signes pulmonaires.','Bilan de sepsis et imagerie cervicothoracique.'],['Amygdalite sans collection.','Inflammation sans signe focal convaincant.','Évaluation clinique ; ne pas drainer à l’aveugle.']])) ,
('L’{anamnèse précise la progression unilatérale}. Demander douleur, otalgie, trismus et apports liquides. Rechercher une aggravation malgré un traitement ou des signes généraux.',paras('L’otalgie du même côté peut être réflexe, malgré une oreille normale. La difficulté croissante à ouvrir la bouche et une voix altérée indiquent un retentissement local.', 'Préciser antécédents d’abcès, infections amygdaliennes répétées, antibiotiques déjà pris, allergies et immunosuppression. Les prélèvements et le choix thérapeutique peuvent en dépendre.')),
('L’{examen compare le voile, les amygdales et la luette}. Une déviation de la luette peut orienter. Son absence ne suffit pas à exclure l’abcès.',paras('Chez un patient respiratoirement stable, observer l’ouverture buccale, le bombement du voile et l’asymétrie. La revue suisse décrit une déviation possible de la luette vers le côté sain, sans en faire un signe constant.', 'Évaluer cou, ganglions, hydratation et constantes. Éviter les explorations agressives en cas de menace respiratoire et faire intervenir une équipe équipée.')),
('L’{approche syndromique associe douleur focale et retentissement}. La collection est suspectée devant un ensemble de signes. La déshydratation et le sepsis doivent être recherchés séparément.',paras('<em>7.1 — Syndrome périamygdalien.</em> Odynophagie unilatérale, otalgie réflexe, trismus et bombement du voile.', '<em>7.2 — Retentissement fonctionnel.</em> Voix modifiée, diminution des boissons et difficulté à gérer la salive.', '<em>7.3 — Extension ou sepsis.</em> Douleur cervicale, torticolis, signes respiratoires ou altération générale imposent un bilan urgent élargi.')),
('Le {diagnostic repose sur l’examen spécialisé}. Une collection peut être confirmée lors d’une ponction ou d’un drainage. L’imagerie est choisie si la localisation ou l’extension reste incertaine.',paras('L’absence de collection démontrée peut correspondre à une inflammation périamygdalienne. La distinction influence la nécessité d’un geste ; elle relève de l’évaluation ORL.', 'Une ponction est un acte médical réalisé dans des conditions adaptées. Le cours ne propose pas de repère de ponction ou de geste à réaliser hors d’un cadre spécialisé.')),
('Les {examens répondent à l’incertitude et à la gravité}. L’imagerie ne doit pas retarder la protection respiratoire. Un prélèvement du foyer est différent d’un simple test streptococcique.',table(['Étape','Utilité'],[['9.a : examen ORL.','Préciser collection probable, accès et retentissement.'],['9.b : prélèvement.','Analyser le pus si un geste est réalisé, selon protocole.'],['9.c : extension.','Imagerie cervicale injectée si doute sur les espaces profonds et patient stable.'],['9.d : sepsis.','Bilan biologique et hémocultures selon gravité, sans retard thérapeutique.']])) ,
('L’{algorithme conduit rapidement au spécialiste}. Le drainage dépend de la collection et du terrain. La sortie n’est envisagée qu’après une réévaluation fonctionnelle.',steps('Évaluer respiration, salive, état général et hydratation.','Obtenir un avis ORL urgent ; adresser à l’hôpital si menace ou impossibilité de boire.','Confirmer la localisation et rechercher l’extension.','Traiter par antibiothérapie et contrôle du foyer selon décision spécialisée.','Vérifier amélioration, reprise des boissons et suivi avant une éventuelle sortie.')),
('La {prise en charge associe contrôle du foyer et traitement anti-infectieux}. Une collection peut nécessiter ponction ou incision-drainage. La voie d’administration dépend notamment de la déglutition et de la gravité.',paras('<em>11.A — Stabilisation.</em> Prise en charge respiratoire si menace, hydratation et antalgie adaptées au terrain.', '<em>11.B — Foyer.</em> Les HUG décrivent ponction, incision-drainage ou amygdalectomie selon la situation. Le choix dépend de l’examen, des récidives et du risque opératoire.', '<em>11.C — Infection.</em> L’antibiothérapie hospitalière doit couvrir les agents plausibles, notamment les anaérobies selon le contexte. Aucun schéma unique ni dose empirique non vérifiée n’est fabriqué ici ; la prescription s’appuie sur le protocole local et la notice de la spécialité retenue.', '<em>11.D — Réévaluation.</em> Surveiller respiration, fièvre, douleur, boissons et signes d’extension. Une absence d’amélioration exige de rechercher un foyer persistant ou une complication.')),
('La {prévention secondaire porte sur la récidive et les signes de retour}. Donner des consignes précises après le geste. L’éventuelle indication d’amygdalectomie se discute avec l’ORL.',paras('Reconsulter immédiatement si gêne respiratoire, salivation inhabituelle, douleur cervicale croissante, fièvre persistante ou incapacité à boire. Ne pas manipuler soi-même la zone drainée.', 'L’amélioration après drainage ne supprime pas le besoin de respecter la prescription et le contrôle prévus. Une récidive mérite une stratégie spécialisée.')),
('Le {point clé est l’asymétrie avec trismus}. Cette combinaison impose de rechercher une collection. Un antibiotique ambulatoire répété ne doit pas retarder l’évaluation du foyer.',paras('La gravité dépend autant du retentissement respiratoire et général que de l’aspect de l’amygdale. Le contrôle de la source infectieuse et la surveillance sont complémentaires.'))]
q=[('Abcès périamygdalien et péritonsillaire sont-ils synonymes ?','Oui.'),('L’exsudat prouve-t-il une collection ?','Non.'),('Quel signe fonctionnel oriente particulièrement ?','Le trismus, dans un tableau unilatéral.'),('L’otalgie peut-elle être réflexe ?','Oui.'),('La luette doit-elle toujours être déviée ?','Non.'),('Une infection EBV exclut-elle cet abcès ?','Non.'),('Que faire si le patient ne gère plus sa salive ?','Évaluer immédiatement la voie aérienne et adresser en urgence.'),('Un test streptococcique remplace-t-il le bilan du foyer ?','Non.'),('Quand l’imagerie est-elle particulièrement utile ?','Si localisation ou extension profonde incertaine, après sécurisation respiratoire.'),('Le drainage est-il un geste à domicile ?','Non.'),('L’antibiotique suffit-il toujours ?','Non, le contrôle de la collection peut être nécessaire.'),('Que vérifier avant une sortie ?','Amélioration, sécurité respiratoire, capacité à boire et suivi.'),('Une douleur cervicale et des signes pulmonaires font craindre quoi ?','Notamment un syndrome de Lemierre.'),('Pourquoi revoir une récidive avec l’ORL ?','Pour une stratégie préventive et une éventuelle indication chirurgicale.')]
produire(4,p,q,(3,4,7))

p=[
('L’{épiglottite aiguë} est une inflammation de l’épiglotte et parfois des tissus supraglottiques voisins. Elle peut obstruer rapidement l’entrée du larynx. Toute suspicion exige une évaluation hospitalière urgente.',paras('La présentation adulte peut être moins brutale que celle de l’enfant. Le terme supraglottite souligne que l’inflammation peut dépasser l’épiglotte.', 'Une gorge peu anormale à l’ouverture buccale n’exclut pas une lésion plus basse. La plainte de déglutition et les signes respiratoires doivent donc être pris au sérieux.')),
('La {vaccination a modifié le contexte pédiatrique}. Les adultes restent concernés. Le caractère rare n’autorise pas à banaliser une présentation compatible.',paras('La revue suisse 2015 décrit la forte diminution pédiatrique après vaccination contre Haemophilus influenzae de type b et la persistance de cas adultes. Ses anciens chiffres d’incidence et de mortalité ne sont pas présentés comme des estimations suisses actuelles.', 'Une immunodépression, une lésion locale ou une exposition thermique peuvent modifier le contexte. L’étiologie n’est pas toujours une infection à Hib.')),
('L’{œdème rétrécit l’entrée de la voie aérienne}. La position spontanée peut aider à maintenir le passage de l’air. La priorité thérapeutique est de préserver cette perméabilité.',table(['Perturbation','Signe ou exploration','Action'],[['Œdème supraglottique.','Voix étouffée, odynophagie, visualisation spécialisée.','Surveillance et contrôle de la voie aérienne.'],['Réduction du passage de l’air.','Stridor, tirage, position penchée en avant.','Équipe anesthésie/ORL et matériel d’abord respiratoire.'],['Infection associée.','Fièvre et prélèvements selon sécurité.','Antibiothérapie hospitalière sans retard évitable.']])+paras('L’épiglotte se situe à l’entrée du larynx. L’enflure peut gêner la respiration même hors de la déglutition ; elle ne doit pas être traitée comme une simple douleur muqueuse.')),
('Les {urgences concurrentes partagent le risque d’obstruction}. Les distinguer ne doit pas retarder les secours. L’absence de tous les signes classiques ne rassure pas à elle seule.',table(['Diagnostic','Contexte discriminant','Priorité'],[['🚩 Angiœdème.','Gonflement après exposition ou médicament, parfois sans fièvre.','Voie aérienne et traitement de la cause.'],['🚩 Abcès profond.','Trismus, torticolis ou tuméfaction cervicale.','Avis ORL et contrôle du foyer.'],['🚩 Corps étranger ou brûlure.','Début brutal après événement précis.','Prise en charge adaptée immédiate.'],['Pharyngite simple.','Respiration et gestion de la salive conservées, pas de signe profond.','Ne retenir qu’après évaluation.']])) ,
('L’{anamnèse doit rester brève si la respiration est menacée}. Demander début, progression, douleur, voix et salivation. Garder le patient dans la position qu’il tolère.',paras('Une impossibilité de s’allonger, une préférence pour la position penchée en avant ou une aggravation rapide sont des informations essentielles. Ne pas provoquer un déplacement ou un examen qui majore la détresse.', 'Si la stabilité le permet, préciser vaccination, immunosuppression, brûlure, traumatisme et exposition toxique. L’identification d’un germe ne précède pas la sécurité respiratoire.')),
('L’{examen est d’abord visuel et respiratoire}. Observer effort, stridor, couleur, voix et salive. L’exploration de la gorge appartient à un milieu capable de gérer une aggravation.',paras('Ne pas forcer l’ouverture buccale ou la position couchée chez une personne suspecte, particulièrement chez l’enfant. Limiter agitation et manipulations inutiles.', 'La laryngoscopie ou nasofibroscopie est organisée par l’équipe expérimentée avec une stratégie respiratoire. Une observation rassurante ponctuelle ne garantit pas l’absence d’aggravation ultérieure.')),
('L’{approche syndromique réunit déglutition et respiration}. Une douleur intense peut précéder les signes respiratoires majeurs. L’état général renseigne sur le retentissement infectieux.',paras('<em>7.1 — Syndrome supraglottique.</em> Odynophagie, voix étouffée et salivation liée à la difficulté d’avaler.', '<em>7.2 — Syndrome obstructif.</em> Stridor inspiratoire, tirage et position de confort ; la cyanose est un signe de gravité.', '<em>7.3 — Syndrome infectieux.</em> Fièvre et altération générale, à évaluer sans retarder la protection des voies aériennes.')),
('Le {diagnostic est confirmé en milieu sécurisé}. La visualisation montre l’atteinte supraglottique. Les examens complémentaires sont secondaires à la stabilisation.',paras('Le tableau clinique suffit pour déclencher une prise en charge urgente. Une confirmation endoscopique peut préciser l’étendue, mais ne doit pas être recherchée dans un cabinet non équipé au prix d’un risque d’obstruction.', 'Une radiographie ou une tomodensitométrie n’est pas un passage obligé avant l’appel aux spécialistes. Leur utilité dépend de la stabilité et d’une question précise, notamment une complication.')),
('Les {examens se font dans un ordre sûr}. Prélever ou imager ne doit pas retarder les gestes vitaux. Les résultats microbiologiques guident ensuite l’adaptation.',table(['Étape','Examen et limite'],[['9.a : respiratoire.','Évaluation clinique continue et monitorage adapté au milieu.'],['9.b : anatomique.','Endoscopie par équipe expérimentée et prête à sécuriser la voie aérienne.'],['9.c : microbiologique.','Prélèvements et hémocultures si réalisables sans retard ni manipulation dangereuse.'],['9.d : complication.','Imagerie selon question et stabilité, sans transport non sécurisé.']])) ,
('L’{algorithme traite la menace respiratoire en premier}. L’antibiothérapie ne remplace pas la surveillance de la voie aérienne. L’évolution peut être rapide.',steps('Suspecter devant odynophagie importante, voix modifiée, salivation ou stridor.','Appeler le 144 et préserver la position de confort.','Faire intervenir anesthésie et ORL dans un milieu équipé.','Sécuriser ou surveiller étroitement la voie aérienne selon l’évaluation spécialisée.','Administrer le traitement étiologique hospitalier et réévaluer l’évolution.')),
('La {prise en charge se déroule à l’hôpital}. Elle associe oxygénation, surveillance et traitement de la cause. Une intubation ou un abord chirurgical peut devenir nécessaire.',paras('<em>11.A — Voie aérienne.</em> L’équipe expérimentée décide de l’abord et prévoit une solution de secours. Ne pas tenter une procédure répétée non maîtrisée.', '<em>11.B — Infection.</em> La revue suisse décrit une antibiothérapie intraveineuse couvrant les germes plausibles, notamment par une céphalosporine de troisième génération selon protocole. La prescription précise dépend du terrain, des allergies et des résultats ; aucun dosage non vérifié n’est ajouté.', '<em>11.C — Traitements associés.</em> Les traitements adjuvants et l’hydratation sont décidés par l’équipe ; ils ne doivent pas créer un faux sentiment de sécurité respiratoire.', '<em>11.D — Surveillance.</em> Maintenir une observation jusqu’à amélioration jugée suffisante. La diminution de la fièvre ne suffit pas à elle seule à autoriser la sortie.')),
('La {prévention inclut la vaccination adaptée}. Vérifier la protection contre Hib selon le plan suisse. Les mesures pour les contacts dépendent de l’agent identifié.',paras('Ne pas transposer le calendrier vaccinal britannique figurant sur la page NHS au calendrier suisse. Les recommandations suisses et l’âge guident le rattrapage.', 'Une cause thermique ou toxique appelle des conseils spécifiques d’évitement. Une vaccination complète n’exclut pas toute épiglottite d’une autre origine.')),
('Le {point clé est la discordance possible entre bouche et gravité}. Une inspection banale ne visualise pas toute la région supraglottique. La sécurisation prime sur la preuve microbiologique.',paras('Stridor, salivation et position penchée en avant ne sont pas des détails accessoires. Ils justifient une filière urgente et une équipe capable de traiter une obstruction.'))]
q=[('L’épiglottite peut-elle toucher l’adulte ?','Oui.'),('Une bouche peu inflammatoire l’exclut-elle ?','Non.'),('Quel risque vital domine ?','L’obstruction des voies aériennes.'),('Faut-il imposer la position couchée ?','Non, préserver la position de confort.'),('Un stridor est-il un signe banal ?','Non.'),('Peut-on forcer un examen pharyngé chez l’enfant suspect ?','Non.'),('Qui doit réaliser l’exploration à risque ?','Une équipe expérimentée dans un milieu équipé.'),('Faut-il attendre une culture pour traiter ?','Non si cela retarde la prise en charge urgente.'),('L’imagerie précède-t-elle toujours les secours ?','Non.'),('Une amélioration de fièvre garantit-elle la sécurité ?','Non.'),('Hib est-il la seule cause ?','Non.'),('Le calendrier NHS s’applique-t-il directement en Suisse ?','Non.'),('Une antibiothérapie dispense-t-elle du contrôle respiratoire ?','Non.'),('Quel numéro d’urgence utilise-t-on en Suisse ?','Le 144.')]
produire(5,p,q,(3,4,7,10))

p=[
('L’{abcès rétropharyngé} est une infection avec collection dans un espace profond derrière le pharynx. Il peut altérer déglutition et respiration. L’extension cervicale ou thoracique en fait une urgence spécialisée.',paras('Une atteinte rétropharyngée se distingue de l’abcès périamygdalien situé autour de l’amygdale. Plusieurs espaces profonds peuvent être impliqués, et l’examen buccal ne montre pas toujours l’ensemble du foyer.', 'Une tuméfaction du mur postérieur peut orienter, mais son absence ne suffit pas à exclure une infection profonde.')),
('Le {contexte infectieux et la présentation cervicale orientent}. Le rang précis de fréquence n’est pas quantifié dans les sources retenues. La gravité dépend de l’extension et du retentissement.',paras('Les supports suisses citent cette infection parmi les causes de mal de gorge grave et d’obstruction haute. Ils ne fournissent pas une incidence suisse récente exploitable pour ce cours.', 'Une infection voisine, un problème dentaire ou un événement local doit être recherché selon l’histoire. La stratégie ne repose pas sur l’âge seul.')),
('La {collection profonde déplace et enflamme les tissus}. Le torticolis et la douleur cervicale peuvent signaler cette extension. Le contrôle du foyer complète le traitement anti-infectieux.',table(['Perturbation','Exploration','Réponse'],[['Collection rétro- ou parapharyngée.','Imagerie cervicale injectée si stabilité.','Drainage ou autre contrôle du foyer selon spécialiste.'],['Œdème et compression.','Salivation, dysphagie, stridor et effort respiratoire.','Sécurisation respiratoire si nécessaire.'],['Extension septique.','État général, bilan infectieux et recherche thoracique ciblée.','Antibiothérapie hospitalière et traitement des complications.']])+paras('Les espaces cervicaux profonds ne sont pas entièrement accessibles à l’inspection de la bouche. Leur continuité explique pourquoi le bilan peut dépasser l’oropharynx.')),
('Le {tri recherche d’abord une obstruction ou un sepsis}. Une douleur cervicale fébrile avec torticolis n’est pas une angine simple. Les diagnostics concurrents doivent être évalués rapidement.',table(['Concurrent','Indice','Action'],[['🚩 Épiglottite.','Voix étouffée, salivation et stridor.','Voies aériennes avec équipe spécialisée.'],['🚩 Abcès périamygdalien.','Bombement du voile et trismus prédominants.','Avis ORL et recherche de collection.'],['🚩 Lemierre.','Douleur jugulaire, reprise fébrile et signes pulmonaires.','Bilan cervicothoracique et hémocultures.'],['Autre cause cervicale.','Histoire de traumatisme, corps étranger ou maladie non infectieuse.','Bilan adapté sans conclure sur une seule image.']])) ,
('L’{anamnèse précise douleur cervicale et déglutition}. Demander torticolis, voix, salive et difficultés respiratoires. Rechercher infection récente, soins dentaires ou geste local.',paras('La chronologie aide à distinguer une aggravation secondaire d’une simple infection de surface. Un refus de bouger le cou ou une posture inhabituelle est utile à signaler.', 'Préciser antibiotiques déjà reçus, immunosuppression et allergies. Interroger sur douleur thoracique ou dyspnée, qui peuvent faire rechercher une extension.')),
('L’{examen doit rester prudent}. Observer position du cou, respiration et capacité à gérer la salive. Une tuméfaction postérieure peut être visible chez un patient stable.',paras('Ne pas forcer les mouvements du cou ni palper agressivement le pharynx. L’évaluation de la voie aérienne et de l’état hémodynamique précède l’examen détaillé.', 'Rechercher trismus, masse cervicale et modification de la voix. Un examen buccal peu contributif ne justifie pas le retour à domicile si les signes profonds persistent.')),
('L’{approche syndromique met en relation cou, pharynx et état général}. Les symptômes peuvent se chevaucher avec d’autres infections profondes. Le tableau doit être documenté sans attendre un signe complet.',paras('<em>7.1 — Syndrome cervical profond.</em> Douleur, torticolis, tuméfaction et limitation fonctionnelle.', '<em>7.2 — Syndrome pharyngo-respiratoire.</em> Dysphagie, salivation, voix étouffée et éventuel stridor.', '<em>7.3 — Syndrome septique ou d’extension.</em> Altération générale et signes thoraciques nécessitent un bilan élargi.')),
('Le {diagnostic associe clinique et imagerie adaptée}. L’image doit distinguer inflammation et collection autant que possible. Son interprétation relève du contexte et de l’équipe spécialisée.',paras('Les HUG décrivent la tomodensitométrie injectée pour les infections para-rétropharyngées. La nécessité de déplacement en imagerie doit être pesée face au risque respiratoire.', 'La présence d’un foyer drainable et l’extension influencent la décision opératoire. Une imagerie ne remplace pas les examens répétés d’un patient qui se dégrade.')),
('Les {examens servent à cartographier et documenter le foyer}. Ils se font après évaluation de la sécurité. Les prélèvements ne retardent pas une prise en charge vitale.',table(['Étape','Objectif'],[['9.a : clinique.','Évaluer voie aérienne, hydratation et sepsis.'],['9.b : imagerie.','Tomodensitométrie cervicale injectée selon indication et stabilité.'],['9.c : microbiologie.','Prélèvements du foyer et hémocultures selon gravité.'],['9.d : extension.','Compléter le bilan thoracique ou vasculaire si signes évocateurs.']])) ,
('L’{algorithme prévoit hospitalisation et contrôle du foyer}. L’antibiothérapie orale d’une angine simple est insuffisante devant une suspicion profonde. La réévaluation détermine la suite.',steps('Identifier les signes cervicaux profonds et les alarmes respiratoires.','Adresser en urgence à une équipe ORL et hospitalière.','Sécuriser la voie aérienne si nécessaire avant l’imagerie.','Documenter le foyer et instaurer antibiothérapie et stratégie de drainage.','Surveiller réponse, respiration et signes d’extension.')),
('La {prise en charge est hospitalière}. Elle combine traitement anti-infectieux et décision de drainage. La surveillance reste nécessaire après le geste initial.',paras('<em>11.A — Stabilisation.</em> Voie aérienne, hydratation et prise en charge du sepsis selon état.', '<em>11.B — Antibiothérapie.</em> Traitement parentéral adapté aux bactéries plausibles, au terrain et aux résistances. La revue suisse cite notamment streptocoques et staphylocoques pour cette localisation ; le protocole spécialisé tient compte de l’ensemble du foyer.', '<em>11.C — Foyer.</em> Les HUG décrivent une approche chirurgicale possible selon extension et collection. La décision ne se déduit pas d’un seul symptôme.', '<em>11.D — Suivi.</em> Contrôler douleur, cou, boissons, état général et respiration. Une aggravation ou une amélioration insuffisante exige une nouvelle évaluation du foyer et des complications.')),
('La {prévention secondaire dépend de la cause initiale}. Traiter un foyer dentaire ou local identifié fait partie du suivi. Les signes de récidive doivent être expliqués.',paras('Une nouvelle difficulté à avaler, un torticolis fébrile ou une douleur thoracique après traitement justifie une réévaluation rapide. Le patient doit connaître le contact hospitalier prévu.', 'Le suivi du drainage, des prélèvements et de l’antibiothérapie doit être organisé avant la sortie. Les conseils ne se limitent pas à terminer une boîte de comprimés.')),
('Le {point clé est le cou douloureux avec retentissement pharyngé}. Une inspection de gorge limitée peut manquer le foyer. La décision tient compte de l’espace profond et de la respiration.',paras('Imagerie, antibiothérapie et geste spécialisé sont complémentaires. Aucun examen ne doit retarder la sécurisation d’une voie aérienne menacée.'))]
q=[('Où siège la collection ?','Dans un espace profond derrière le pharynx.'),('Est-ce identique à un abcès périamygdalien ?','Non.'),('Quel signe cervical est évocateur ?','Un torticolis fébrile ou une douleur cervicale avec dysphagie.'),('Une gorge peu anormale l’exclut-elle ?','Non.'),('Faut-il forcer les mouvements du cou ?','Non.'),('Quel examen d’imagerie décrivent les HUG ?','Une tomodensitométrie injectée selon indication et stabilité.'),('L’imagerie passe-t-elle avant la sécurité respiratoire ?','Non.'),('Une angine simple et une infection profonde ont-elles le même parcours ?','Non.'),('Une culture pharyngée suffit-elle à localiser le foyer ?','Non.'),('Quand rechercher une extension thoracique ?','Si le contexte et les signes la font suspecter.'),('Un drainage est-il toujours décidé à distance ?','Non, il dépend de l’évaluation spécialisée.'),('Quelle voie antibiotique est généralement requise au départ ?','Une voie parentérale selon la prise en charge hospitalière.'),('Que faire si le patient se dégrade après le traitement initial ?','Réévaluer rapidement le foyer et les complications.'),('Quel message de sortie est essentiel ?','Reconsulter rapidement pour récidive de dysphagie, torticolis fébrile ou signes respiratoires.')]
produire(6,p,q,(3,4,7))

p=[
('Le {syndrome de Lemierre} associe une infection oropharyngée à une thrombophlébite septique jugulaire. Des emboles infectieux peuvent atteindre les poumons. Il s’agit d’une urgence hospitalière.',paras('La veine jugulaire interne peut être atteinte par l’extension d’une infection cervicale. Le thrombus infecté peut disséminer par voie sanguine, contrairement à une simple inflammation pharyngée.', 'Fusobacterium necrophorum est l’agent classiquement associé, mais d’autres bactéries sont possibles. Le diagnostic ne doit pas attendre une identification microbiologique typique.')),
('Le {contexte classique est celui d’un adolescent ou jeune adulte}. Le syndrome reste rare. Un âge différent ne l’exclut pas.',paras('La publication belge 2022 décrit une prédominance chez les adolescents et jeunes adultes, tout en rapportant un cas plus âgé. Elle ne fournit pas une incidence suisse actuelle ; aucun chiffre de fréquence n’est déduit ici.', 'Les HUG attirent l’attention sur une fièvre qui apparaît ou reprend après le début d’une angine, avec douleur ou tuméfaction unilatérale du cou. La chronologie compte davantage qu’un délai obligatoire rigide.')),
('La {thrombose septique relie le foyer cervical au poumon}. L’infection peut gagner la jugulaire puis emboliser. Les lésions pulmonaires peuvent donc révéler l’origine cervicale.',table(['Étape','Exploration','Réponse'],[['Infection oropharyngée ou cervicale.','Examen ORL et imagerie du foyer.','Contrôle de la source infectieuse.'],['Thrombophlébite de la jugulaire.','Imagerie cervicale avec contraste selon situation.','Antibiothérapie et évaluation spécialisée.'],['Emboles septiques pulmonaires.','Imagerie thoracique devant signes respiratoires.','Traitement de l’infection et drainage d’un empyème si nécessaire.']])+paras('La publication belge décrit des nodules ou masses pulmonaires excavés et une thrombose jugulaire à l’imagerie. Ces signes doivent être reliés au contexte septique ; d’autres sources d’emboles infectieux restent possibles.')),
('Le {tri recherche sepsis et défaillance respiratoire}. Une aggravation générale après une angine est une alarme. Les diagnostics concurrents ne doivent pas retarder le traitement.',table(['Concurrent','Discriminant','Conduite'],[['🚩 Abcès cervical profond.','Foyer local et collection, avec ou sans thrombose.','Avis ORL et contrôle du foyer.'],['🚩 Endocardite droite.','Autre source possible d’emboles septiques pulmonaires.','Bilan infectieux et cardiaque selon contexte.'],['Pneumonie isolée.','Atteinte thoracique sans explication cervicale suffisante.','Ne pas omettre le cou si l’histoire commence par une angine.'],['Thrombose non septique.','Contexte et microbiologie différents.','Interprétation spécialisée, sans négliger une infection.']])) ,
('L’{anamnèse reconstruit la séquence gorge, cou puis symptômes généraux}. Demander reprise fébrile, douleur latérale du cou et gêne thoracique. Rechercher les traitements déjà pris.',paras('La douleur peut longer la région sternocléidomastoïdienne ou sous-mandibulaire selon le support HUG. Une toux, une dyspnée ou une douleur thoracique peuvent signaler une atteinte pulmonaire.', 'Préciser foyer dentaire, cathéter, consommation injectable ou autre source infectieuse lorsque pertinent, car les emboles septiques ne sont pas spécifiques de Lemierre.')),
('L’{examen apprécie cou, respiration et circulation}. La recherche d’une tuméfaction cervicale reste prudente. L’absence de masse visible ne suffit pas à rassurer.',paras('Évaluer constantes, état mental, perfusion et effort respiratoire. Examiner gorge et cou si la sécurité le permet, puis rechercher signes pulmonaires et autres foyers.', 'Le diagnostic n’exige pas que toutes les manifestations soient déjà présentes. Une dégradation générale justifie un bilan urgent même avant une triade complète.')),
('L’{approche syndromique relie trois territoires}. Le foyer ORL, la thrombose cervicale et les foyers à distance constituent le cadre classique. Leur expression varie d’un patient à l’autre.',paras('<em>7.1 — Syndrome infectieux oropharyngé.</em> Angine ou foyer profond antérieur à l’aggravation.', '<em>7.2 — Syndrome cervical vasculaire.</em> Douleur ou tuméfaction latérale, associée à la thrombophlébite suspectée.', '<em>7.3 — Syndrome septique embolique.</em> Fièvre persistante, altération générale et atteinte pulmonaire ou autre foyer à distance.')),
('Le {diagnostic repose sur le faisceau clinique, microbiologique et radiologique}. L’imagerie montre la thrombose et les foyers associés. L’hémoculture documente l’agent sans être toujours immédiatement contributive.',paras('La publication belge met en avant l’association d’une pharyngite, d’une thrombose cervicale et de lésions pulmonaires excavées. Cette association est très évocatrice dans un contexte septique.', 'L’agent peut être différent de Fusobacterium. Des antibiotiques pris avant les prélèvements peuvent compliquer leur interprétation ; une culture négative ne remplace pas l’analyse clinique.')),
('Les {examens cherchent le foyer, la thrombose et les emboles}. Les prélèvements doivent inclure la question des bactéries anaérobies. Les examens ne retardent pas le traitement d’un sepsis.',table(['Étape','Examen'],[['9.a : microbiologie.','Hémocultures et prélèvements du foyer, laboratoire informé de la suspicion.'],['9.b : cou.','Imagerie cervicale avec contraste pour jugulaire et foyer profond.'],['9.c : thorax.','Imagerie selon signes respiratoires et recherche d’emboles septiques.'],['9.d : complications.','Bilan d’organe et autres localisations guidés par l’examen.']])) ,
('L’{algorithme déclenche une prise en charge hospitalière rapide}. Le traitement cible l’infection et ses foyers. La thrombose ne doit pas faire oublier sa nature septique.',steps('Suspecter devant reprise fébrile et signes cervicaux ou pulmonaires après une angine.','Évaluer et traiter la gravité respiratoire et circulatoire.','Prélever sans retard significatif, puis instaurer le traitement anti-infectieux hospitalier.','Documenter jugulaire, foyer cervical et atteinte thoracique.','Discuter drainage et autres mesures avec infectiologie, ORL et équipes concernées.')),
('La {prise en charge exige antibiothérapie et contrôle des foyers}. Elle est adaptée aux prélèvements et à l’évolution. Une complication pleurale peut nécessiter un drainage.',paras('<em>11.A — Sepsis.</em> Stabilisation hospitalière avec surveillance des organes et support selon besoin.', '<em>11.B — Antibiotiques.</em> Le traitement doit être actif sur les germes plausibles, dont les anaérobies, puis ajusté à l’agent et à sa sensibilité. Les sources retenues ne définissent pas un schéma suisse unique valable pour tous les patients ; aucune dose universelle n’est inventée.', '<em>11.C — Foyers.</em> Évaluer le drainage d’une collection cervicale, pulmonaire ou pleurale. Le cas belge illustre un empyème ayant nécessité un drainage en complément des antibiotiques.', '<em>11.D — Thrombose et suivi.</em> L’anticoagulation ne découle pas automatiquement du mot thrombose ; son éventuelle indication est discutée au cas par cas par l’équipe spécialisée. Une revue danoise de 2016 soulignait le manque de preuve. Une analyse observationnelle publiée en 2026 suggère moins de progression du thrombus, sans bénéfice clair sur les autres critères majeurs ; elle ne justifie pas une prescription systématique. Suivre l’évolution clinique et radiologique selon les complications.')),
('La {prévention secondaire repose sur la reconnaissance précoce d’une aggravation}. Une angine initialement simple peut changer de présentation. Donner des consignes sur la reprise fébrile et les signes cervicothoraciques.',paras('Une antibiothérapie systématique de toute angine n’est pas proposée comme garantie contre Lemierre. Le signal utile est l’évolution inattendue qui impose une nouvelle évaluation.', 'Après hospitalisation, organiser le contrôle infectieux, des foyers drainés et des séquelles selon l’équipe. La durée et les examens de suivi sont individualisés.')),
('Le {point clé est la continuité entre gorge, jugulaire et poumon}. Un tableau pulmonaire septique peut avoir une origine cervicale. Ne pas attendre la totalité des signes pour agir.',paras('La rareté de Lemierre et la fréquence des angines expliquent le piège diagnostique. Le traitement doit suivre la gravité réelle et la documentation du foyer.'))]
q=[('Quelle veine est classiquement concernée ?','La jugulaire interne.'),('Quel germe est classique ?','Fusobacterium necrophorum.'),('Est-il le seul agent possible ?','Non.'),('Quel enchaînement clinique doit alerter ?','Angine puis reprise fébrile avec douleur cervicale ou signes pulmonaires.'),('Les emboles pulmonaires sont-ils nécessairement stériles ?','Non, ils sont septiques dans ce syndrome.'),('Un âge plus élevé exclut-il Lemierre ?','Non.'),('Faut-il attendre une triade complète ?','Non.'),('Quel examen documente la thrombose cervicale ?','Une imagerie adaptée, notamment avec contraste selon le contexte.'),('Pourquoi informer le laboratoire ?','Pour orienter les prélèvements et la recherche microbiologique, notamment anaérobie.'),('Une culture négative suffit-elle à exclure ?','Non.'),('Quel autre foyer peut causer des emboles septiques pulmonaires ?','Une endocardite droite, entre autres.'),('Un empyème peut-il nécessiter un drainage ?','Oui.'),('L’anticoagulation est-elle automatiquement obligatoire ?','Non, la décision est spécialisée et individualisée.'),('Faut-il prévenir ce syndrome par antibiotique dans toute angine ?','Ce n’est pas la stratégie suisse décrite ; reconnaître l’aggravation est essentiel.')]
produire(7,p,q,(3,4,7,11,15,16))
